sys_script_client.script:
function onLoad() {
    var getAssignmentGrp = g_form.getValue('assignment_group');
    var currentUrl = top.location.href;
    var regex = /-1_uid_\d+/;
    var match = currentUrl.match(regex);

    var fieldsReadOnlyAfterSubmit = ['client_function', 'our_function', 'client_organization_name', 'case_type', 'our_business_unit', 'our_organization_name', 'originator_name', 'u_source'];
    fieldsReadOnlyAfterSubmit.forEach(function(fields) {
        if (g_form.getValue(fields) != "") {
            g_form.setReadOnly(fields, true);
        }
    });
    if ((match) && (!getAssignmentGrp)) {

        var fieldsToHide = ['our_organization_name', 'number', 'event_date_time', 'u_source', 'draft_comments', 'work_notes', 'x_hsb11_mss_trus_0_kocid', 'hsbc_entity', 'hsbc_product'];
        fieldsToHide.forEach(function(field) {
            g_form.setVisible(field, false);
        });

        var fieldsToMandatory = ['client_function', 'client_organization_name', 'assignment_group', 'our_function', 'short_description', 'originator_name', 'our_business_unit'];
        fieldsToMandatory.forEach(function(fields) {
            g_form.setMandatory(fields, true);
        });



        g_form.setValue('case_type', 'manual_outgoing');
        g_form.setValue('assigned_to', g_user.userID);
        g_form.setValue('originator_name', g_user.getFullName());
		g_form.setValue('u_source','HSBC');
		g_form.setValue('priority', 4);


        if (g_user.hasRole('x_hsb11_mss_taskiz.taskizeCustodyUsers')) {
            g_form.setValue('our_function', 'Custody');
        } else if (g_user.hasRole('x_hsb11_mss_taskiz.taskizeCollateralUsers')) {
            g_form.setValue('our_function', 'Collateral Mgmt');
        }


        var ourFunction = g_form.getValue('our_function');

        var ga = new GlideAjax('MSSTaskizeUtils');
        ga.addParam('sysparm_name', 'getUserGroupType');
        ga.addParam('sysparm_ourFunction', ourFunction);
        ga.getXMLAnswer(function(response) {
            var result = JSON.parse(response);
            var userGroupSysIds = result.userGroupSysIds;
            var finalOptions = result.finalOptions;

            if (userGroupSysIds.length === 1) {
                g_form.setValue('assignment_group', userGroupSysIds[0]);
                g_form.setReadOnly('assignment_group', true);
            } else {
                g_form.setValue('assignment_group', '');
                g_form.setReadOnly('assignment_group', false);
            }

            if (finalOptions.length === 1) {
                g_form.setValue('our_business_unit', finalOptions[0]);
                g_form.setReadOnly('our_business_unit', true);
            } else if (finalOptions.every(function(type) {
                    return type === finalOptions[0];
                })) {
                g_form.setValue('our_business_unit', finalOptions[0]);
                g_form.setReadOnly('our_business_unit', true);
            } else {
                g_form.setReadOnly('our_business_unit', false);
                g_form.clearOptions('our_business_unit');
                g_form.addOption('our_business_unit', '', '-- None --');

                finalOptions.forEach(function(option) {
                    g_form.addOption('our_business_unit', option, option);
                });
            }
        });

        g_form.setReadOnly('our_function', true);
        g_form.setReadOnly('originator_name', true);
    }
    if (g_form.getValue('case_type') == 'manual_outgoing') {
        g_form.setVisible('escalation', true);
    } else {
        g_form.setVisible('escalation', false);
    }
}
